"""Consolidate labeled feedback into periodic LLM-authored lessons."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


LESSON_WINDOW = 8
RECENT_CASES = 4
MAX_LESSONS = 16

LEARNING_PROMPT = """Review these problem, attempt, and correct-output records.

Find one concise lesson that could transfer to future problems. Give priority
to distinctions shown by incorrect attempts. Avoid memorizing individual
answers or asserting a rule that the records do not support. Return JSON:
{{"lesson": "[one concise transferable lesson]"}}

Records:
{records}
"""

PREDICT_PROMPT = """Solve the problem using relevant learned lessons and recent examples.

{memory_section}

**Problem:**
{input}

Lessons summarize patterns from earlier feedback. Check that each applies to
this problem before using it. Treat individual examples as evidence, not rules.
Respond in JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}"""


class LessonWindowMemory(MemorySystem):
    """Replace completed feedback windows with short learned lessons."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.lessons: list[str] = []
        self.pending: list[dict[str, Any]] = []
        self.recent: list[dict[str, str]] = []

    def _distill(self, records: list[dict[str, Any]]) -> str:
        prompt = LEARNING_PROMPT.format(
            records=json.dumps(records, ensure_ascii=False, indent=2)
        )
        response = self.call_llm(prompt)
        lesson = extract_json_field(response, "lesson").strip()
        if not lesson:
            lesson = response.strip()
        return lesson[:1000]

    def _format_memory(self) -> str:
        sections = []
        if self.lessons:
            sections.append(
                "Lessons learned from earlier feedback:\n"
                + "\n".join(f"- {lesson}" for lesson in self.lessons)
            )

        unfinished = self.pending[:-RECENT_CASES] if len(self.pending) > RECENT_CASES else []
        cases = [
            {"input": item["input"], "target": item["ground_truth"]}
            for item in unfinished
        ]
        cases.extend(self.recent[-RECENT_CASES:])
        if cases:
            lines = ["Recent or not-yet-consolidated examples:"]
            for case in cases:
                lines.append(f"- Input: {case['input']}\n  Correct output: {case['target']}")
            sections.append("\n".join(lines))

        return "\n\n".join(sections) if sections else "No feedback has been learned yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        memory_section = self._format_memory()
        prompt = PREDICT_PROMPT.format(memory_section=memory_section, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_lessons": len(self.lessons),
            "num_pending": len(self.pending),
            "num_recent_cases": min(len(self.recent), RECENT_CASES),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            item = {
                "input": str(result.get("raw_question") or result["input"]),
                "prediction": str(result["prediction"]),
                "ground_truth": str(result["ground_truth"]),
                "was_correct": bool(result["was_correct"]),
            }
            self.pending.append(item)
            self.recent.append({"input": item["input"], "target": item["ground_truth"]})
            self.recent = self.recent[-RECENT_CASES:]

            while len(self.pending) >= LESSON_WINDOW:
                window = self.pending[:LESSON_WINDOW]
                lesson = self._distill(window)
                if lesson:
                    self.lessons.append(lesson)
                    self.lessons = self.lessons[-MAX_LESSONS:]
                self.pending = self.pending[LESSON_WINDOW:]

    def get_context_length(self) -> int:
        return len(self._format_memory())

    def get_state(self) -> str:
        return json.dumps(
            {"lessons": self.lessons, "pending": self.pending, "recent": self.recent},
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.lessons = data.get("lessons", [])
        self.pending = data.get("pending", [])
        self.recent = data.get("recent", [])

"""Present query-matched, label-pair contrast cards learned from examples."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using these learned contrasts between labels.

{contrast_section}

**Problem:**
{input}

The contrast cards summarize words that distinguished the labeled examples in
each pair. Treat them as weak clues, compare the full problem, and select the
best-supported answer. Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_CARDS = 8
MAX_CUES_PER_SIDE = 3


def _tokens(text: str) -> set[str]:
    return set(re.findall(r"[a-z]{2,}", text.lower()))


class PairwiseContrastMemory(MemorySystem):
    """Learn discriminative terms for pairs of competing labels."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.class_token_docs: dict[str, Counter[str]] = {}
        self.class_docs: Counter[str] = Counter()

    def _cues(
        self, own: Counter[str], other: Counter[str], own_docs: int, other_docs: int
    ) -> list[str]:
        ranked = []
        for token, own_count in own.items():
            # Smoothed log-odds on document presence favors terms that separate
            # the two labels instead of terms that are frequent everywhere.
            other_count = other[token]
            score = math.log((own_count + 0.5) / (own_docs - own_count + 0.5))
            score -= math.log(
                (other_count + 0.5) / (other_docs - other_count + 0.5)
            )
            if score > 0:
                ranked.append((score, token))
        return [token for _, token in sorted(ranked, reverse=True)[:MAX_CUES_PER_SIDE]]

    def _cards(self) -> list[dict[str, Any]]:
        labels = sorted(self.class_token_docs, key=str.casefold)
        cards = []
        for index, left in enumerate(labels):
            for right in labels[index + 1 :]:
                cards.append(
                    {
                        "left": left,
                        "right": right,
                        "left_cues": self._cues(
                            self.class_token_docs[left],
                            self.class_token_docs[right],
                            self.class_docs[left],
                            self.class_docs[right],
                        ),
                        "right_cues": self._cues(
                            self.class_token_docs[right],
                            self.class_token_docs[left],
                            self.class_docs[right],
                            self.class_docs[left],
                        ),
                    }
                )
        return cards

    def _format_contrasts(self, query: str) -> str:
        query_tokens = _tokens(query)
        ranked = []
        for card in self._cards():
            left_hits = query_tokens.intersection(card["left_cues"])
            right_hits = query_tokens.intersection(card["right_cues"])
            hits = len(left_hits) + len(right_hits)
            if hits or not query:
                ranked.append((hits, max(len(left_hits), len(right_hits)), card))

        ranked.sort(
            key=lambda item: (
                item[0],
                item[1],
                len(item[2]["left_cues"]) + len(item[2]["right_cues"]),
            ),
            reverse=True,
        )
        if not ranked:
            return "No learned contrast cues match this problem."

        lines = ["Query-matched label contrasts (left-side cues / right-side cues):"]
        for _, _, card in ranked[:MAX_CARDS]:
            left = ", ".join(card["left_cues"]) or "no cue"
            right = ", ".join(card["right_cues"]) or "no cue"
            lines.append(f"- {card['left']} versus {card['right']}: {left} / {right}")
        return "\n".join(lines)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        contrast_section = self._format_contrasts(input)
        prompt = PROMPT_TEMPLATE.format(contrast_section=contrast_section, input=input)
        response = self.call_llm(prompt)
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_label_pairs": len(self._cards()),
            "contrast_chars": len(contrast_section),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            label = str(result["ground_truth"])
            text = str(result.get("raw_question") or result["input"])
            self.class_docs[label] += 1
            self.class_token_docs.setdefault(label, Counter()).update(_tokens(text))

    def get_context_length(self) -> int:
        return len(self._format_contrasts(""))

    def get_state(self) -> str:
        return json.dumps(
            {
                "class_token_docs": {
                    label: dict(counts)
                    for label, counts in self.class_token_docs.items()
                },
                "class_docs": dict(self.class_docs),
            },
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.class_token_docs = {
            label: Counter(counts)
            for label, counts in data.get("class_token_docs", {}).items()
        }
        self.class_docs = Counter(data.get("class_docs", {}))
"""Label-grouped casebook prompt with explicit hypothesis comparison."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem by comparing the label hypotheses in the casebook.

{examples_section}

**Problem:**
{input}

**Comparison process:**
1. Identify the most informative facts in the problem.
2. Compare those facts with the cases under each plausible label.
3. For the strongest candidate, state its best supporting fact and the
   strongest conflicting fact. Eliminate candidates with weaker overall fit.
4. Use the complete pattern; a single shared detail is not enough.

Respond in JSON format:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


class HypothesisGrouped(MemorySystem):
    """Store labeled cases and present them in competing label groups."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 9999,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self) -> str:
        """Group every case under its label and obey the shared context cap."""
        if not self.examples:
            return ""
        groups: dict[str, list[dict[str, str]]] = {}
        for example in self.examples[-self.max_examples :]:
            groups.setdefault(example["target"], []).append(example)

        parts = []
        total_chars = 0
        for label in sorted(groups, key=str.casefold):
            cases = groups[label]
            header = f"LABEL: {label} ({len(cases)})"
            case_parts = [header]
            for example in cases:
                question = example.get("raw_question", example["input"])
                case_parts.append(f"- {question}")
            part = "\n".join(case_parts)
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        examples_section = self._format_examples_section()
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_label_hypotheses": len({example["target"] for example in self.examples}),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])
"""Retrieve hard, cross-label example pairs near the current problem."""

import json
import math
import re
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem by checking it against these boundary pairs.

{pairs_section}

**Problem:**
{input}

Each pair contains similar earlier problems with different correct outputs.
Identify the detail that separates the two cases, then compare the complete
problem before choosing an answer. Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_BOUNDARY_PAIRS = 24
MAX_CONTEXT_PAIRS = 4


def _tokens(text: str) -> set[str]:
    return set(re.findall(r"[a-z]{2,}", text.lower()))


def _overlap(left: set[str], right: set[str]) -> float:
    denominator = min(len(left), len(right))
    return len(left & right) / denominator if denominator else 0.0


class BoundaryPairMemory(MemorySystem):
    """Build a compact bank of similar examples carrying different labels."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.boundary_pairs: dict[str, dict[str, Any]] = {}

    @staticmethod
    def _pair_key(left: str, right: str) -> str:
        return json.dumps(sorted((left, right)), ensure_ascii=False)

    def _add_example(self, example: dict[str, str]) -> None:
        current_tokens = _tokens(example["input"])
        for prior in self.examples:
            if prior["target"] == example["target"]:
                continue
            similarity = _overlap(current_tokens, _tokens(prior["input"]))
            key = self._pair_key(prior["target"], example["target"])
            existing = self.boundary_pairs.get(key)
            if existing is None or similarity > existing["similarity"]:
                self.boundary_pairs[key] = {
                    "left": prior,
                    "right": example,
                    "similarity": similarity,
                }
        self.examples.append(example)

    def _idf(self) -> dict[str, float]:
        document_frequency: dict[str, int] = {}
        for example in self.examples:
            for token in _tokens(example["input"]):
                document_frequency[token] = document_frequency.get(token, 0) + 1
        total = max(1, len(self.examples))
        return {
            token: math.log((total + 1) / (frequency + 1)) + 1
            for token, frequency in document_frequency.items()
        }

    @staticmethod
    def _vector(text: str, idf: dict[str, float]) -> dict[str, float]:
        counts: dict[str, int] = {}
        for token in re.findall(r"[a-z]{2,}", text.lower()):
            counts[token] = counts.get(token, 0) + 1
        vector = {token: count * idf.get(token, 1.0) for token, count in counts.items()}
        norm = math.sqrt(sum(value * value for value in vector.values()))
        return {token: value / norm for token, value in vector.items()} if norm else {}

    @staticmethod
    def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
        return sum(value * right.get(token, 0.0) for token, value in left.items())

    def _select_pairs(self, query: str) -> list[dict[str, Any]]:
        if not self.boundary_pairs:
            return []

        idf = self._idf()
        query_vector = self._vector(query, idf)
        candidates = sorted(
            self.boundary_pairs.values(),
            key=lambda pair: pair["similarity"],
            reverse=True,
        )[:MAX_BOUNDARY_PAIRS]
        if not query:
            return candidates[:MAX_CONTEXT_PAIRS]
        ranked = []
        for pair in candidates:
            left, right = pair["left"], pair["right"]
            left_score = self._cosine(query_vector, self._vector(left["input"], idf))
            right_score = self._cosine(query_vector, self._vector(right["input"], idf))
            ranked.append((max(left_score, right_score), pair))
        ranked.sort(key=lambda item: item[0], reverse=True)
        return [pair for score, pair in ranked[:MAX_CONTEXT_PAIRS] if score > 0]

    def _format_pairs(self, query: str) -> str:
        selected = self._select_pairs(query)
        if not selected:
            return "No learned boundary pairs are available for this problem."

        lines = ["Similar problems with contrasting labels:"]
        for index, pair in enumerate(selected, start=1):
            left, right = pair["left"], pair["right"]
            lines.append(
                f"Pair {index}:\n"
                f"- Problem: {left['input']}\n  Correct output: {left['target']}\n"
                f"- Problem: {right['input']}\n  Correct output: {right['target']}"
            )
        return "\n\n".join(lines)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        pairs_section = self._format_pairs(input)
        response = self.call_llm(PROMPT_TEMPLATE.format(pairs_section=pairs_section, input=input))
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_boundary_pairs": len(self.boundary_pairs),
            "num_retrieved_pairs": len(self._select_pairs(input)),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            self._add_example(
                {
                    "input": str(result.get("raw_question") or result["input"]),
                    "target": str(result["ground_truth"]),
                }
            )
        if len(self.boundary_pairs) > MAX_BOUNDARY_PAIRS:
            kept = sorted(
                self.boundary_pairs.items(),
                key=lambda item: item[1]["similarity"],
                reverse=True,
            )[:MAX_BOUNDARY_PAIRS]
            self.boundary_pairs = dict(kept)

    def get_context_length(self) -> int:
        return len(self._format_pairs(""))

    def get_state(self) -> str:
        return json.dumps(
            {
                "examples": self.examples,
                "boundary_pairs": list(self.boundary_pairs.values()),
            },
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])
        pairs = data.get("boundary_pairs")
        if pairs is None:
            self.boundary_pairs = {}
            examples = self.examples
            self.examples = []
            for example in examples:
                self._add_example(example)
        else:
            self.boundary_pairs = {
                self._pair_key(pair["left"]["target"], pair["right"]["target"]): pair
                for pair in pairs
            }
"""Compressed class-wise lexical evidence learned from labeled examples."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Answer the problem using the learned class evidence profiles.

{profiles_section}

**Problem:**
{input}

The listed words are recurring clues from labeled examples, not rules. Compare
the complete meaning of the problem with every plausible profile, including
similar alternatives. Answer in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

PROFILE_CUES = 5


def _tokens(text: str) -> list[str]:
    return re.findall(r"[a-z]{2,}", text.lower())


class ClassEvidenceProfiles(MemorySystem):
    """Keep sufficient per-label token counts instead of storing raw cases."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.class_counts: dict[str, Counter[str]] = {}
        self.class_docs: Counter[str] = Counter()
        self.global_counts: Counter[str] = Counter()

    def _profile_rows(self) -> list[tuple[str, int, list[str]]]:
        vocabulary_size = max(1, len(self.global_counts))
        global_total = sum(self.global_counts.values())
        rows = []
        for label in sorted(self.class_counts):
            counts = self.class_counts[label]
            class_total = sum(counts.values())
            scored = []
            for token, count in counts.items():
                class_rate = (count + 0.5) / (class_total + 0.5 * vocabulary_size)
                global_rate = (self.global_counts[token] + 0.5) / (
                    global_total + 0.5 * vocabulary_size
                )
                score = math.log(class_rate / global_rate)
                scored.append((score, count, token))
            cues = [
                token
                for score, _, token in sorted(scored, reverse=True)
                if score > 0
            ][:PROFILE_CUES]
            if not cues:
                cues = [token for token, _ in counts.most_common(PROFILE_CUES)]
