\u5728\u5e7f\u5dde\u5e02\u8d8a\u79c0\u533a\u4e00\u95f4\u5496\u5561\u5385\u5185\u5c063\u4e07\u5143\u9001\u7ed9\u4e8e\u67d0\u7532\u3002\r\n2013\u5e7411\u670818\u65e5\uff0c\u9ec4\u67d0\u67d0\u63a5\u5230\u5434\u5ddd\u5e02\u4eba\u6c11\u68c0\u5bdf\u9662\u529e\u6848\u4eba\u5458\u7684\u7535\u8bdd\u901a\u77e5\u540e\uff0c\u81ea\u884c\u6765\u5230\u5434\u5ddd\u5e02\u4eba\u6c11\u68c0\u5bdf\u9662\u63a5\u53d7\u8c03\u67e5\uff0c\u5e76\u5982\u5b9e\u4ea4\u4ee3\u4e86\u5176\u4e3a\u4e86\u83b7\u53d6\u9ad8\u989d\u62c6\u8fc1\u8865\u507f\u6b3e\u800c\u5411\u4e8e\u67d0\u7532\u884c\u8d3f3\u4e07\u5143\u7684\u72af\u7f6a\u4e8b\u5b9e\u30022014\u5e743\u670817\u65e5\uff0c\u5434\u5ddd\u5e02\u4eba\u6c11\u68c0\u5bdf\u9662\u5bf9\u9ec4\u67d0\u67d0\u6d89\u5acc\u00d7\u00d7\u4e00\u6848\u7acb\u6848\u4fa6\u67e5\u3002\r\n\u4e0a\u8ff0\u4e8b\u5b9e\uff0c\u88ab\u544a\u4eba\u9ec4\u67d0\u67d0\u5728\u5f00\u5ead\u5ba1\u7406\u8fc7\u7a0b\u4e2d\u4ea6\u65e0\u5f02\u8bae\uff0c\u4e14\u6709\u516c\u8bc9\u673a\u5173\u63d0\u4f9b\u7684\uff0c\u7ecf\u5ead\u5ba1\u8d28\u8bc1\u3001\u8ba4\u8bc1\u7684\u8bc1\u4eba\u4e8e\u67d0\u7532\u7684\u8bc1\u8a00\uff0c\u62c6\u8fc1\u5b89\u7f6e\u8865\u507f\u534f\u8bae\u4e66\uff0c\u4e13\u9879\u8d44\u91d1\u652f\u51fa\u51ed\u8bc1\uff0c\u8f6c\u8d26\u51ed\u8bc1\uff0c\u6536\u636e\uff0c\u59d4\u6258\u4e66\uff0c\u65b0\u5efa\u8302\u540d\u81f3\u6e5b\u6c5f\u94c1\u8def\u9879\u76ee\u5f81\u5730\u62c6\u8fc1\u8865\u507f\u5b89\u7f6e\u65b9\u6848\uff0c\u4e8e\u67d0\u7532\u7684\u4efb\u804c\u53ca\u6237\u7c4d\u8bc1\u660e\u6750\u6599\uff0c\u88ab\u544a\u4eba\u9ec4\u67d0\u67d0\u7684\u6237\u7c4d\u8bc1\u660e\u7b49\u8bc1\u636e\u4e88\u4ee5\u8bc1\u5b9e\uff0c\u8db3\u4ee5\u8ba4\u5b9a\u3002\r\n",
      "target": "\u884c\u8d3f",
      "raw_question": "\u4e8b\u5b9e:\u7ecf\u5ba1\u7406\u67e5\u660e\uff0c\u88ab\u544a\u4eba\u9ec4\u67d0\u67d0\u7684\u7236\u4eb2\u9ec4\u67d0\u7532\u4f4d\u4e8e\u5434\u5ddd\u5e02\u957f\u5c90\u9547\u9ec4\u5740\u6751\u7684\u4e00\u95f4\u623f\u5c4b\u5728\u8302\u6e5b\u94c1\u8def\u5efa\u8bbe\u5f81\u6536\u62c6\u8fc1\u8303\u56f4\u5185\u3002\u56e0\u9ec4\u67d0\u7532\u5e74\u9f84\u8f83\u9ad8\uff0c\u8eab\u4f53\u4e0d\u597d\uff0c\u4fbf\u59d4\u6258\u9ec4\u67d0\u67d0\u5168\u6743\u8d1f\u8d23\u76f8\u5173\u7684\u623f\u5c4b\u62c6\u8fc1\u8865\u507f\u4e8b\u5b9c\u3002\u6309\u62c6\u8fc1\u8865\u507f\u6807\u51c6\uff0c\u5176\u623f\u5c4b\u6700\u521d\u8bc4\u4f30\u8865\u507f\u6b3e\u662f35\u4e07\u591a\u5143\uff0c\u9ec4\u67d0\u67d0\u8ba4\u4e3a\u8865\u507f\u4ef7\u683c\u4f4e\uff0c\u4e0d\u540c\u610f\u62c6\u8fc1\u3002\u540e\u4e3a\u4e86\u83b7\u53d6\u66f4\u9ad8\u7684\u8865\u507f\u6b3e\uff0c\u9ec4\u67d0\u67d0\u627e\u5230\u8302\u6e5b\u94c1\u8def\u6709\u9650\u8d23\u4efb\u516c\u53f8\u8d1f\u8d23\u5434\u5ddd\u8def\u6bb5\u5f81\u5730\u62c6\u8fc1\u5de5\u4f5c\u7684\u4e8e\u67d0\u7532\u5e2e\u5fd9\u63d0\u9ad8\u4ed6\u7684\u62c6\u8fc1\u8865\u507f\u6b3e\uff0c\u5e76\u8bb8\u8bfa\u4e8b\u6210\u540e\u7ed9\u4e8e\u67d0\u7532\u597d\u5904\u8d39\u3002\u4e8e\u67d0\u7532\u542c\u540e\u8868\u793a\u540c\u610f\u3002\u5728\u4e8e\u67d0\u7532\u7684\u5e2e\u52a9\u4e0b\uff0c\u9ec4\u67d0\u67d0\u6700\u7ec8\u53d6\u5f9769\u4e07\u591a\u5143\u7684\u623f\u5c4b\u62c6\u8fc1\u8865\u507f\u6b3e\u3002\u4e3a\u4e86\u611f\u8c22\u4e8e\u67d0\u7532\u7684\u5e2e\u5fd9\uff0c2013\u5e74\u6625\u8282\u524d\uff0c\u9ec4\u67d0\u67d0\u5728\u5e7f\u5dde\u5e02\u8d8a\u79c0\u533a\u4e00\u95f4\u5496\u5561\u5385\u5185\u5c063\u4e07\u5143\u9001\u7ed9\u4e8e\u67d0\u7532\u3002\r\n2013\u5e7411\u670818\u65e5\uff0c\u9ec4\u67d0\u67d0\u63a5\u5230\u5434\u5ddd\u5e02\u4eba\u6c11\u68c0\u5bdf\u9662\u529e\u6848\u4eba\u5458\u7684\u7535\u8bdd\u901a\u77e5\u540e\uff0c\u81ea\u884c\u6765\u5230\u5434\u5ddd\u5e02\u4eba\u6c11\u68c0\u5bdf\u9662\u63a5\u53d7\u8c03\u67e5\uff0c\u5e76\u5982\u5b9e\u4ea4\u4ee3\u4e86\u5176\u4e3a\u4e86\u83b7\u53d6\u9ad8\u989d\u62c6\u8fc1\u8865\u507f\u6b3e\u800c\u5411\u4e8e\u67d0\u7532\u884c\u8d3f3\u4e07\u5143\u7684\u72af\u7f6a\u4e8b\u5b9e\u30022014\u5e743\u670817\u65e5\uff0c\u5434\u5ddd\u5e02\u4eba\u6c11\u68c0\u5bdf\u9662\u5bf9\u9ec4\u67d0\u67d0\u6d89\u5acc\u00d7\u00d7\u4e00\u6848\u7acb\u6848\u4fa6\u67e5\u3002\r\n\u4e0a\u8ff0\u4e8b\u5b9e\uff0c\u88ab\u544a\u4eba\u9ec4\u67d0\u67d0\u5728\u5f00\u5ead\u5ba1\u7406\u8fc7\u7a0b\u4e2d\u4ea6\u65e0\u5f02\u8bae\uff0c\u4e14\u6709\u516c\u8bc9\u673a\u5173\u63d0\u4f9b\u7684\uff0c\u7ecf\u5ead\u5ba1\u8d28\u8bc1\u3001\u8ba4\u8bc1\u7684\u8bc1\u4eba\u4e8e\u67d0\u7532\u7684\u8bc1\u8a00\uff0c\u62c6\u8fc1\u5b89\u7f6e\u8865\u507f\u534f\u8bae\u4e66\uff0c\u4e13\u9879\u8d44\u91d1\u652f\u51fa\u51ed\u8bc1\uff0c\u8f6c\u8d26\u51ed\u8bc1\uff0c\u6536\u636e\uff0c\u59d4\u6258\u4e66\uff0c\u65b0\u5efa\u8302\u540d\u81f3\u6e5b\u6c5f\u94c1\u8def\u9879\u76ee\u5f81\u5730\u62c6\u8fc1\u8865\u507f\u5b89\u7f6e\u65b9\u6848\uff0c\u4e8e\u67d0\u7532\u7684\u4efb\u804c\u53ca\u6237\u7c4d\u8bc1\u660e\u6750\u6599\uff0c\u88ab\u544a\u4eba\u9ec4\u67d0\u67d0\u7684\u6237\u7c4d\u8bc1\u660e\u7b49\u8bc1\u636e\u4e88\u4ee5\u8bc1\u5b9e\uff0c\u8db3\u4ee5\u8ba4\u5b9a\u3002\r\n"
    },
    {
      "input": "\u8bf7\u4f60\u6a21\u62df\u6cd5\u5b98\u4f9d\u636e\u4e0b\u9762\u4e8b\u5b9e\u7ed9\u51fa\u7f6a\u540d\u3002\u8bf7\u5148\u8fdb\u884c\u63a8\u7406\u5206\u6790\uff0c\u7136\u540e\u5c06\u6700\u7ec8\u7b54\u6848\u5199\u5728[\u7f6a\u540d]\u548c<eoa>\u4e4b\u95f4\u3002\n\n\u683c\u5f0f\u793a\u4f8b\uff1a\n- \u5355\u4e2a\u7f6a\u540d: [\u7f6a\u540d]\u76d7\u7a83<eoa>\n- \u591a\u4e2a\u7f6a\u540d: [\u7f6a\u540d]\u76d7\u7a83;\u8bc8\u9a97<eoa>\n\n\n## \u6848\u4ef6\u4e8b\u5b9e\n\u4e8b\u5b9e:\u9ed1\u9f99\u6c5f\u7701\u5df4\u5f66\u53bf\u4eba\u6c11\u68c0\u5bdf\u9662\u6307\u63a7\uff0c2012\u5e746\u67089\u65e5\uff0c\u88ab\u544a\u4eba\u5f20\u67d0\u67d0\u8c0e\u79f0\u4ee5\u79df\u8f66\u7684\u540d\u4e49\u5c06\u88ab\u5bb3\u4eba\u674e\u67d0\u67d0\u7684\u8f7f\u8f66\u9a97\u8d70\u540e\uff0c\u5f20\u67d0\u67d0\u5c06\u9a97\u5f97\u7684\u8f7f\u8f66\u62b5\u62bc\u7ed9\u5176\u670b\u53cb\u7126\u67d0\u67d0\u5e76\u501f\u6b3e\u4eba\u6c11\u5e0115,000\u5143\uff0c\u6b64\u540e\u674e\u67d0\u67d0\u591a\u6b21\u7ed9\u5f20\u67d0\u67d0\u6253\u7535\u8bdd\u8981\u8f66\u65f6\u5f20\u67d0\u67d0\u62d2\u4e0d\u8fd8\u8f66\uff0c\u4e4b\u540e\u5f20\u67d0\u67d0\u9003\u5f80\u5916\u5730\u3002\u516c\u8bc9\u673a\u5173\u8ba4\u4e3a\uff0c\u88ab\u544a\u4eba\u5f20\u67d0\u67d0\u89e6\u72af\u4e86\u300a\u4e2d\u534e\u4eba\u6c11\u5171\u548c\u56fd\u5211\u6cd5\u300b\u00d7\u00d7\u7684\u89c4\u5b9a\uff0c\u6784\u6210\u00d7\u00d7\uff0c\u5e94\u5f53\u4ee5\u00d7\u00d7\u8ffd\u7a76\u5176\u5211\u4e8b\u8d23\u4efb\u3002\u9488\u5bf9\u4e0a\u8ff0\u6307\u63a7\uff0c\u516c\u8bc9\u673a\u5173\u63d0\u4f9b\u4e86\u76f8\u5e94\u7684\u8bc1\u636e\u3002\r\n",
      "target": "\u8bc8\u9a97;\u7ec4\u7ec7\u3001\u5f3a\u8feb\u3001\u5f15\u8bf1\u3001\u5bb9\u7559\u3001\u4ecb\u7ecd\u5356\u6deb;\u5f15\u8bf1\u3001\u5bb9\u7559\u3001\u4ecb\u7ecd\u5356\u6deb",
      "raw_question": "\u4e8b\u5b9e:\u9ed1\u9f99\u6c5f\u7701\u5df4\u5f66\u53bf\u4eba\u6c11\u68c0\u5bdf\u9662\u6307\u63a7\uff0c2012\u5e746\u67089\u65e5\uff0c\u88ab\u544a\u4eba\u5f20\u67d0\u67d0\u8c0e\u79f0\u4ee5\u79df\u8f66\u7684\u540d\u4e49\u5c06\u88ab\u5bb3\u4eba\u674e\u67d0\u67d0\u7684\u8f7f\u8f66\u9a97\u8d70\u540e\uff0c\u5f20\u67d0\u67d0\u5c06\u9a97\u5f97\u7684\u8f7f\u8f66\u62b5\u62bc\u7ed9\u5176\u670b\u53cb\u7126\u67d0\u67d0\u5e76\u501f\u6b3e\u4eba\u6c11\u5e0115,000\u5143\uff0c\u6b64\u540e\u674e\u67d0\u67d0\u591a\u6b21\u7ed9\u5f20\u67d0\u67d0\u6253\u7535\u8bdd\u8981\u8f66\u65f6\u5f20\u67d0\u67d0\u62d2\u4e0d\u8fd8\u8f66\uff0c\u4e4b\u540e\u5f20\u67d0\u67d0\u9003\u5f80\u5916\u5730\u3002\u516c\u8bc9\u673a\u5173\u8ba4\u4e3a\uff0c\u88ab\u544a\u4eba\u5f20\u67d0\u67d0\u89e6\u72af\u4e86\u300a\u4e2d\u534e\u4eba\u6c11\u5171\u548c\u56fd\u5211\u6cd5\u300b\u00d7\u00d7\u7684\u89c4\u5b9a\uff0c\u6784\u6210\u00d7\u00d7\uff0c\u5e94\u5f53\u4ee5\u00d7\u00d7\u8ffd\u7a76\u5176\u5211\u4e8b\u8d23\u4efb\u3002\u9488\u5bf9\u4e0a\u8ff0\u6307\u63a7\uff0c\u516c\u8bc9\u673a\u5173\u63d0\u4f9b\u4e86\u76f8\u5e94\u7684\u8bc1\u636e\u3002\r\n"
    },
    {
      "input": "\u8bf7\u4f60\u6a21\u62df\u6cd5\u5b98\u4f9d\u636e\u4e0b\u9762\u4e8b\u5b9e\u7ed9\u51fa\u7f6a\u540d\u3002\u8bf7\u5148\u8fdb\u884c\u63a8\u7406\u5206\u6790\uff0c\u7136\u540e\u5c06\u6700\u7ec8\u7b54\u6848\u5199\u5728[\u7f6a\u540d]\u548c<eoa>\u4e4b\u95f4\u3002\n\n\u683c\u5f0f\u793a\u4f8b\uff1a\n- \u5355\u4e2a\u7f6a\u540d: [\u7f6a\u540d]\u76d7\u7a83<eoa>\n- \u591a\u4e2a\u7f6a\u540d: [\u7f6a\u540d]\u76d7\u7a83;\u8bc8\u9a97<eoa>\n\n\n## \u6848\u4ef6\u4e8b\u5b9e\n\u4e8b\u5b9e:\u516c\u8bc9\u673a\u5173\u6307\u63a7\u79f0\uff0c2013\u5e748\u67087\u65e518\u65f6\u8bb8\uff0c\u88ab\u544a\u4eba\u5b8b\u67d0\u56e0\u6b20\u88ab\u5bb3\u4eba\u9648\u67d0\u7532\u94b1\u4e00\u4e8b\uff0c\u4e0e\u9648\u53d1\u751f\u7ea0\u7eb7\u3002\u540e\u5b8b\u67d0\u548c\u9093\u67d0\u67d0\u3001\u9648\u67d0\u4e59\u3001\u9648\u67d0\u4e19\u3001\u83ab\u67d0\u67d0\uff08\u540e\u56db\u4eba\u5747\u53e6\u6848\u5904\u7406\uff09\u5148\u540e\u53bb\u5230\u4e1c\u839e\u5e02\u5927\u6717\u9547\u6c34\u53e3\u6751\u7535\u5f71\u9662\u95e8\u524d\u627e\u5230\u9648\u67d0\u7532\uff0c\u5b8b\u67d0\u4e0e\u9648\u67d0\u7532\u53d1\u751f\u4e89\u6267\uff0c\u5e76\u6301\u94a2\u7ba1\u6bb4\u6253\u9648\u67d0\u7532\uff0c\u540e\u5b8b\u67d0\u7b49\u4eba\u79bb\u5f00\u3002\u540e\u6765\uff0c\u5b8b\u67d0\u548c\u9093\u67d0\u67d0\u3001\u9648\u67d0\u4e59\u3001\u9648\u67d0\u4e19\u3001\u83ab\u67d0\u67d0\u7b49\u4eba\u6301\u94a2\u7ba1\u53bb\u5230\u9648\u67d0\u7532\u7ecf\u8425\u7684\u4f4d\u4e8e\u5927\u6717\u9547\u5723\u5802\u6751\u7f8e\u666f\u4e2d\u8def\uff0a\uff0a\uff0a\u53f7\u5e97\u94fa\uff0c\u6253\u7838\u5e97\u94fa\u5185\u7684\u51b0\u7bb1\u3001\u7535\u8111\u663e\u793a\u5c4f\u7b49\u8d22\u7269\uff08\u5171\u4ef7\u503c2609.78\u5143\uff09\uff0c\u540e\u9003\u79bb\u73b0\u573a\u3002\u516c\u5b89\u673a\u5173\u7ecf\u4fa6\u67e5\uff0c\u4e8e\u540c\u5e7411\u670814\u65e512\u65f6\u8bb8\u5728\u5927\u6717\u9547\u5df7\u5c3e\u6751\u91d1\u73ab\u7470\u7f51\u5427\u6293\u83b7\u5b8b\u67d0\u3002\u7ecf\u6cd5\u533b\u9274\u5b9a\uff0c\u88ab\u5bb3\u4eba\u9648\u67d0\u7532\u6240\u53d