      "target": "\u6545\u610f\u4f24\u5bb3;\u6545\u610f\u6bc1\u574f\u8d22\u7269",
      "raw_question": "\u4e8b\u5b9e:\u516c\u8bc9\u673a\u5173\u6307\u63a7\u79f0\uff0c2013\u5e748\u67087\u65e518\u65f6\u8bb8\uff0c\u88ab\u544a\u4eba\u5b8b\u67d0\u56e0\u6b20\u88ab\u5bb3\u4eba\u9648\u67d0\u7532\u94b1\u4e00\u4e8b\uff0c\u4e0e\u9648\u53d1\u751f\u7ea0\u7eb7\u3002\u540e\u5b8b\u67d0\u548c\u9093\u67d0\u67d0\u3001\u9648\u67d0\u4e59\u3001\u9648\u67d0\u4e19\u3001\u83ab\u67d0\u67d0\uff08\u540e\u56db\u4eba\u5747\u53e6\u6848\u5904\u7406\uff09\u5148\u540e\u53bb\u5230\u4e1c\u839e\u5e02\u5927\u6717\u9547\u6c34\u53e3\u6751\u7535\u5f71\u9662\u95e8\u524d\u627e\u5230\u9648\u67d0\u7532\uff0c\u5b8b\u67d0\u4e0e\u9648\u67d0\u7532\u53d1\u751f\u4e89\u6267\uff0c\u5e76\u6301\u94a2\u7ba1\u6bb4\u6253\u9648\u67d0\u7532\uff0c\u540e\u5b8b\u67d0\u7b49\u4eba\u79bb\u5f00\u3002\u540e\u6765\uff0c\u5b8b\u67d0\u548c\u9093\u67d0\u67d0\u3001\u9648\u67d0\u4e59\u3001\u9648\u67d0\u4e19\u3001\u83ab\u67d0\u67d0\u7b49\u4eba\u6301\u94a2\u7ba1\u53bb\u5230\u9648\u67d0\u7532\u7ecf\u8425\u7684\u4f4d\u4e8e\u5927\u6717\u9547\u5723\u5802\u6751\u7f8e\u666f\u4e2d\u8def\uff0a\uff0a\uff0a\u53f7\u5e97\u94fa\uff0c\u6253\u7838\u5e97\u94fa\u5185\u7684\u51b0\u7bb1\u3001\u7535\u8111\u663e\u793a\u5c4f\u7b49\u8d22\u7269\uff08\u5171\u4ef7\u503c2609.78\u5143\uff09\uff0c\u540e\u9003\u79bb\u73b0\u573a\u3002\u516c\u5b89\u673a\u5173\u7ecf\u4fa6\u67e5\uff0c\u4e8e\u540c\u5e7411\u670814\u65e512\u65f6\u8bb8\u5728\u5927\u6717\u9547\u5df7\u5c3e\u6751\u91d1\u73ab\u7470\u7f51\u5427\u6293\u83b7\u5b8b\u67d0\u3002\u7ecf\u6cd5\u533b\u9274\u5b9a\uff0c\u88ab\u5bb3\u4eba\u9648\u67d0\u7532\u6240\u53d7\u635f\u4f24\u4e3a\u91cd\u4f24\uff0c\u4f24\u6b8b\u516d\u7ea7\u3002\r\n\u516c\u8bc9\u673a\u5173\u5e76\u5411\u6cd5\u5ead\u63d0\u4f9b\u4e86\u76f8\u5e94\u8bc1\u636e\uff0c\u636e\u6b64\u8ba4\u4e3a\u88ab\u544a\u4eba\u5b8b\u67d0\u7684\u884c\u4e3a\u5df2\u89e6\u72af\u4e86\u300a\u4e2d\u534e\u4eba\u6c11\u5171\u548c\u56fd\u5211\u6cd5\u300b\u00d7\u00d7\u3001\u00d7\u00d7\u7684\u89c4\u5b9a\uff0c\u6784\u6210\u4e86\u00d7\u00d7\u3001\u5bfb\u8845\u6ecb\u4e8b\u7f6a\