    {
      "input": "\u8bf7\u4f60\u6a21\u62df\u6cd5\u5b98\u4f9d\u636e\u4e0b\u9762\u4e8b\u5b9e\u7ed9\u51fa\u7f6a\u540d\u3002\u8bf7\u5148\u8fdb\u884c\u63a8\u7406\u5206\u6790\uff0c\u7136\u540e\u5c06\u6700\u7ec8\u7b54\u6848\u5199\u5728[\u7f6a\u540d]\u548c<eoa>\u4e4b\u95f4\u3002\n\n\u683c\u5f0f\u793a\u4f8b\uff1a\n- \u5355\u4e2a\u7f6a\u540d: [\u7f6a\u540d]\u76d7\u7a83<eoa>\n- \u591a\u4e2a\u7f6a\u540d: [\u7f6a\u540d]\u76d7\u7a83;\u8bc8\u9a97<eoa>\n\n\n## \u6848\u4ef6\u4e8b\u5b9e\n\u4e8b\u5b9e:\u7ecf\u5ba1\u7406\u67e5\u660e\uff0c2009\u5e74\u88ab\u544a\u4eba\u5218\u67d0\u5728\u664b\u5dde\u5e02\u65b0\u4e16\u7eaa\u5546\u57ce\u6210\u7acbXXX\u5546\u8d38\u6709\u9650\u516c\u53f8\u5e76\u62c5\u4efb\u603b\u7ecf\u7406\uff0c2014\u5e74\u524d\u540e\uff0c\u4e3a\u5f00\u5c55\u5176\u516c\u53f8\u7684\u4e1a\u52a1\u5ba3\u4f20\uff0c\u88ab\u544a\u4eba\u5218\u67d0\u5229\u7528\u5230\u5706\u901a\u5feb\u9012\u516c\u53f8\u6536\u53d1\u90ae\u4ef6\u7684\u673a\u4f1a\uff0c\u5728\u5706\u901a\u5feb\u9012\u7684\u5de5\u4f5c\u4eba\u5458\u4e0d\u77e5\u60c5\u7684\u60c5\u51b5\u4e0b\uff0c\u4ece\u5706\u901a\u516c\u53f8\u7a83\u53d620167\u4efd\u5706\u901a\u901f\u9012\u7684\u5feb\u9012\u5355\u636e\uff0c\u5e76\u5b89\u6392\u516c\u53f8\u7684\u5de5\u4f5c\u4eba\u5458\u8fdb\u884c\u6574\u7406\uff0c\u7136\u540e\u6309\u7167\u5feb\u9012\u5355\u636e\u4e0a\u9762\u8bb0\u8f7d\u7684\u4e2a\u4eba\u4fe1\u606f\u4e2d\u53ca\u624b\u673a\u53f7\u7801\uff0c\u7528\u53f7\u7801\u4e3a0311-8XXXXXXX\u7684\u7535\u8bdd\uff0c\u9010\u4e2a\u8054\u7cfb\u5ba3\u4f20XXX\u5546\u8d38\u6709\u9650\u516c\u53f8\u7535\u5546\u57f9\u8bad\u4e8b\u5b9c\u3002\r\n\u4e0a\u8ff0\u4e8b\u5b9e\uff0c\u88ab\u544a\u4eba\u5728\u5f00\u5ead\u5ba1\u7406\u8fc7\u7a0b\u4e2d\u4ea6\u65e0\u5f02\u8bae\uff0c\u5e76\u6709\u8bc1\u4eba\u90ed\u67d0\u3001\u8d75\u67d0\u3001\u5e08\u67d0\u8bc1\u8a00\u3001\u664b\u5dde\u5e02\u516c\u5b89\u5c40\u53d7\u6848\u767b\u8bb0\u8868\u3001\u7acb\u6848\u51b3\u5b9a\u4e66\u3001\u641c\u67e5\u7b14\u5f55\u3001\u88ab\u6263\u62bc\u7684\u5706\u901a\u5feb\u9012\u5355\u7167\u7247\u