            self.class_docs[label] += 1
            self.global_counts.update(tokens)

    def get_context_length(self) -> int:
        return len(self._format_profiles_section())

    def get_state(self) -> str:
        return json.dumps(
            {
                "class_counts": {
                    label: dict(counts) for label, counts in self.class_counts.items()
                },
                "class_docs": dict(self.class_docs),
                "global_counts": dict(self.global_counts),
            },
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.class_counts = {
            label: Counter(counts)
            for label, counts in data.get("class_counts", {}).items()
        }
        self.class_docs = Counter(data.get("class_docs", {}))
        self.global_counts = Counter(data.get("global_counts", {}))
"""Query-adaptive retrieval of diverse, label-contrasting demonstrations."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem using the labeled examples as contrasts.

{examples_section}

**Problem:**
{input}

Compare the complete pattern in the problem with the examples. Pay attention to
how examples with different labels differ, and do not copy a label based on one
shared detail. Give the best supported answer in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 12000
MAX_SELECTED = 5


def _tokens(text: str) -> list[str]:
    return re.findall(r"[a-z]{2,}", text.lower())


class ContrastiveRetrieval(MemorySystem):
    """Retrieve query-relevant demonstrations while reducing label redundancy."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    @staticmethod
    def _example_text(example: dict[str, str]) -> str:
        return example.get("raw_question") or example["input"]

    @staticmethod
    def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
        dot = sum(value * right.get(token, 0.0) for token, value in left.items())
        left_norm = math.sqrt(sum(value * value for value in left.values()))
        right_norm = math.sqrt(sum(value * value for value in right.values()))
        return dot / (left_norm * right_norm) if left_norm and right_norm else 0.0

    def _select_examples(self, query: str) -> list[dict[str, str]]:
        if not self.examples:
            return []

        doc_freq: Counter[str] = Counter()
        for example in self.examples:
            doc_freq.update(set(_tokens(self._example_text(example))))
        total = len(self.examples)

        def vector(text: str) -> dict[str, float]:
            counts = Counter(_tokens(text))
            return {
                token: count * (math.log((total + 1) / (doc_freq[token] + 1)) + 1)
                for token, count in counts.items()
            }

        vectors = [vector(self._example_text(example)) for example in self.examples]
        query_vector = vector(query)
        relevance = [self._cosine(query_vector, item) for item in vectors]
        remaining = set(range(total))
        selected: list[int] = []
        selected_labels: set[str] = set()

        while remaining and len(selected) < MAX_SELECTED:
            def rank(index: int) -> float:
                redundancy = max(
                    (self._cosine(vectors[index], vectors[chosen]) for chosen in selected),
                    default=0.0,
                )
                label_bonus = 0.08 if self.examples[index]["target"] not in selected_labels else 0.0
                return relevance[index] + label_bonus - 0.30 * redundancy

            best = max(remaining, key=rank)
            selected.append(best)
            selected_labels.add(self.examples[best]["target"])
            remaining.remove(best)

        selected.sort(key=lambda index: relevance[index], reverse=True)
        chosen = []
        chars = 0
        for index in selected:
            example = self.examples[index]
            question = self._example_text(example)
            part = f"Case: {question}\nLabel: {example['target']}"
            if chars + len(part) > MAX_CHARS:
                continue
            chosen.append(example)
            chars += len(part) + 2
        return chosen

    def _format_examples_section(self, query: str = "") -> str:
        selected = self._select_examples(query)
        if not selected:
            return ""
        return "Contrasting labeled cases:\n\n" + "\n\n".join(
            f"Case: {self._example_text(example)}\nLabel: {example['target']}"
            for example in selected
        )

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        selected = self._select_examples(input)
        examples_section = "Contrasting labeled cases:\n\n" + "\n\n".join(
            f"Case: {self._example_text(example)}\nLabel: {example['target']}"
            for example in selected
        ) if selected else ""
        prompt = PROMPT_TEMPLATE.format(examples_section=examples_section, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_examples": len(selected),
            "num_distinct_labels": len({example["target"] for example in selected}),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            example = {"input": result["input"], "target": result["ground_truth"]}
            if "raw_question" in result:
                example["raw_question"] = result["raw_question"]
            self.examples.append(example)

    def get_context_length(self) -> int:
        return len(self._format_examples_section())

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])
"""Label-grouped casebook prompt with explicit hypothesis comparison."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem by comparing the label hypotheses in the casebook.

{examples_section}

**Problem:**
{input}

**Comparison process:**
1. Identify the most informative facts in the problem.
2. Compare those facts with the cases under each plausible label.
3. For the strongest candidate, state its best supporting fact and the
   strongest conflicting fact. Eliminate candidates with weaker overall fit.
4. Use the complete pattern; a single shared detail is not enough.

Respond in JSON format:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


class HypothesisGrouped(MemorySystem):
    """Store labeled cases and present them in competing label groups."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 9999,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self) -> str:
        """Group every case under its label and obey the shared context cap."""
        if not self.examples:
            return ""
        groups: dict[str, list[dict[str, str]]] = {}
        for example in self.examples[-self.max_examples :]:
            groups.setdefault(example["target"], []).append(example)

        parts = []
        total_chars = 0
        for label in sorted(groups, key=str.casefold):
            cases = groups[label]
            header = f"LABEL: {label} ({len(cases)})"
            case_parts = [header]
            for example in cases:
                question = example.get("raw_question", example["input"])
                case_parts.append(f"- {question}")
            part = "\n".join(case_parts)
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        examples_section = self._format_examples_section()
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_label_hypotheses": len({example["target"] for example in self.examples}),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])

